{
  "title": "Is script B ready for every discharge?",
  "setting": "A nursing unit, before shift change",
  "mission": "Decide whether the unit should use **script B for every discharge** or keep comparing two approved ways to explain instructions. Patients who miss a step on the first try are retaught with either script.",
  "deadline": "Recommendation to the nurse manager by 3:00 p.m.",
  "panels": [
    {
      "title": "First-try teach-back",
      "metrics": [
        {
          "label": "Script A",
          "value": "25 of 40",
          "note": "62.5% repeated both steps correctly"
        },
        {
          "label": "Script B",
          "value": "29 of 40",
          "note": "72.5% repeated both steps correctly"
        }
      ],
      "note": "Patients were assigned to the two approved scripts across shifts. Nurses reteach missed steps before discharge."
    }
  ],
  "team": [
    {
      "id": "manager",
      "role": "Nurse manager",
      "expertise": "Needs a clear recommendation without disrupting discharge work.",
      "ai": false
    },
    {
      "id": "quality",
      "role": "Quality nurse",
      "expertise": "Tracks first-try results and keeps the comparison consistent across shifts.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Checks counts, estimates sample needs, and runs the statistical test.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "evidence",
      "label": "Evidence for a unit-wide change",
      "start": 20,
      "goodWhen": "high"
    },
    {
      "id": "slack",
      "label": "Time before a decision",
      "start": 75,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Tell a real difference from chance",
      "practice": "Take two groups of 40 with a small gap and write one sentence about why the gap might be chance."
    },
    {
      "id": "size",
      "name": "Choose a sample size",
      "practice": "Write down how big a gap would matter, then ask what group size could reliably detect it."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one comparison to a colleague in two sentences without saying it proves what will happen to every patient."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "manager",
          "text": "Script B is ahead by 10 percentage points. Could we use it on every shift?"
        },
        {
          "from": "quality",
          "text": "That's only 40 patients per script. A few different results would change the gap."
        }
      ],
      "prompt": "What do you do before recommending a change?",
      "choices": [
        {
          "id": "check",
          "text": "Ask {{ai}} whether 40 per group is enough to judge a 10-point gap.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "A hypothesis test checks whether a gap this large could reasonably arise by chance if the scripts work equally well. With 40 per group, this gap could. To reliably detect a gap near 10 points, plan for roughly 350 or more per group; 400 gives some margin."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 15
            },
            {
              "meter": "slack",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked whether the apparent lead could be chance before treating it as a finding.",
              "example": null
            },
            {
              "skill": "size",
              "kind": "good",
              "text": "You asked how much data this decision needs, rather than relying on the size of the gap alone.",
              "example": null
            }
          ],
          "next": "plan"
        },
        {
          "id": "more-first",
          "text": "Ask {{quality}} to collect another 40 patients per group before testing.",
          "quality": "fair",
          "replies": [
            {
              "from": "quality",
              "text": "I can do that. We still don't know whether 80 per group will be enough for the decision you want to make."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 5
            },
            {
              "meter": "slack",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "size",
              "kind": "improve",
              "text": "More observations help, but choose a target based on the gap that matters before deciding when to stop.",
              "example": null
            }
          ],
          "next": "unchecked"
        },
        {
          "id": "recommend-now",
          "text": "Tell {{manager}} the 10-point lead is enough to switch every shift.",
          "quality": "weak",
          "replies": [
            {
              "from": "manager",
              "text": "I'll hold the switch for now. I need to know whether that lead is reliable."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "slack",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "A gap in small groups is a reason to investigate, not yet a reason to change every shift.",
              "example": "“Script B is ahead so far, but this gap could be chance.”"
            }
          ],
          "next": "unchecked"
        }
      ]
    },
    {
      "id": "plan",
      "messages": [
        {
          "from": "manager",
          "text": "Waiting weeks has a staffing cost. Do we need to wait for the full comparison?"
        },
        {
          "from": "quality",
          "text": "I can keep both approved scripts in use and score the first try the same way on every shift."
        }
      ],
      "prompt": "How do you balance a quicker answer against a reliable one?",
      "choices": [
        {
          "id": "full-plan",
          "text": "Continue to 400 per group, then have {{ai}} check the final counts.",
          "quality": "strong",
          "replies": [
            {
              "from": "manager",
              "text": "That takes longer, but it gives us a basis for a unit-wide decision."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 45
            },
            {
              "meter": "slack",
              "change": -30
            }
          ],
          "timeJump": {
            "label": "Three weeks later",
            "panel": {
              "title": "First-try teach-back",
              "metrics": [
                {
                  "label": "Script A",
                  "value": "250 of 400",
                  "note": "62.5% repeated both steps correctly"
                },
                {
                  "label": "Script B",
                  "value": "290 of 400",
                  "note": "72.5% repeated both steps correctly"
                }
              ],
              "note": "Both approved scripts remained in use across shifts. Nurses retaught every missed step."
            }
          },
          "notes": [
            {
              "skill": "size",
              "kind": "good",
              "text": "You chose a group size suited to the 10-point gap and accepted the time it would take.",
              "example": null
            }
          ],
          "next": "verified"
        },
        {
          "id": "short-plan",
          "text": "Stop at 80 per group so {{manager}} gets an answer sooner.",
          "quality": "fair",
          "replies": [
            {
              "from": "quality",
              "text": "I'll collect the extra results, but that is well short of the target {{ai}} estimated."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 10
            },
            {
              "meter": "slack",
              "change": -10
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "First-try teach-back",
              "metrics": [
                {
                  "label": "Script A",
                  "value": "50 of 80",
                  "note": "62.5% repeated both steps correctly"
                },
                {
                  "label": "Script B",
                  "value": "58 of 80",
                  "note": "72.5% repeated both steps correctly"
                }
              ],
              "note": "The gap is still 10 percentage points. No test of these new counts has been run."
            }
          },
          "notes": [
            {
              "skill": "size",
              "kind": "improve",
              "text": "A shorter wait helps staffing, but 80 per group is still too small for the planned decision.",
              "example": null
            }
          ],
          "next": "unverified"
        },
        {
          "id": "pitch-early",
          "text": "Recommend script B now and describe the early lead as settled.",
          "quality": "weak",
          "replies": [
            {
              "from": "manager",
              "text": "I can't approve a unit-wide switch on that description. Bring me a recommendation that reflects what we know."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "slack",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "The sample-size check found that the early lead could be chance. Carry that caution into your recommendation.",
              "example": "“B is ahead, but we need more patients before calling the difference reliable.”"
            }
          ],
          "next": "unverified"
        }
      ]
    },
    {
      "id": "unchecked",
      "messages": [
        {
          "from": "manager",
          "text": "The unit-wide switch is still on hold. Can you give me a comparison we can defend?"
        },
        {
          "from": "quality",
          "text": "I can keep assigning patients to both scripts across shifts while we decide how many results we need."
        }
      ],
      "prompt": "What is your next step?",
      "choices": [
        {
          "id": "recover-plan",
          "text": "Ask {{ai}} for a sample target, then collect to 400 per group and check the result.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "For a 10-point gap near these rates, roughly 350 or more per group is a reasonable target. The early counts alone do not settle the question."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 50
            },
            {
              "meter": "slack",
              "change": -35
            }
          ],
          "timeJump": {
            "label": "Three weeks later",
            "panel": {
              "title": "First-try teach-back",
              "metrics": [
                {
                  "label": "Script A",
                  "value": "250 of 400",
                  "note": "62.5% repeated both steps correctly"
                },
                {
                  "label": "Script B",
                  "value": "290 of 400",
                  "note": "72.5% repeated both steps correctly"
                }
              ],
              "note": "Both approved scripts remained in use across shifts. Nurses retaught every missed step."
            }
          },
          "notes": [
            {
              "skill": "size",
              "kind": "good",
              "text": "You set a sample target before making the unit-wide call, even though it delayed the answer.",
              "example": null
            }
          ],
          "next": "verified"
        },
        {
          "id": "collect-quickly",
          "text": "Collect another 40 per group and make the call from those counts.",
          "quality": "fair",
          "replies": [
            {
              "from": "quality",
              "text": "I can bring you those counts in four days. We still won't have checked how much data this call needs."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 10
            },
            {
              "meter": "slack",
              "change": -10
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "First-try teach-back",
              "metrics": [
                {
                  "label": "Script A",
                  "value": "50 of 80",
                  "note": "62.5% repeated both steps correctly"
                },
                {
                  "label": "Script B",
                  "value": "58 of 80",
                  "note": "72.5% repeated both steps correctly"
                }
              ],
              "note": "The gap is still 10 percentage points. No sample plan or test has been run."
            }
          },
          "notes": [
            {
              "skill": "size",
              "kind": "improve",
              "text": "Collecting more data is useful, but first check whether the planned amount can answer the question.",
              "example": null
            }
          ],
          "next": "unverified"
        },
        {
          "id": "press-switch",
          "text": "Press for a unit-wide switch based on the lead already observed.",
          "quality": "weak",
          "replies": [
            {
              "from": "manager",
              "text": "I'm holding the switch. Tell me what the numbers support, not just which script is ahead."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "slack",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Without checking chance and sample size, the early lead is not enough to justify a unit-wide switch.",
              "example": null
            }
          ],
          "next": "unverified"
        }
      ]
    },
    {
      "id": "verified",
      "messages": [
        {
          "from": "ai",
          "text": "The final counts are 250 of 400 for A and 290 of 400 for B. A hypothesis test asks how often a gap this large or larger would appear by chance if the scripts worked equally well. The answer is about 3 in 1,000 comparisons like this one."
        },
        {
          "from": "manager",
          "text": "That sounds useful. How should I describe it to nurses without promising too much?"
        }
      ],
      "prompt": "What recommendation do you give {{manager}}?",
      "choices": [
        {
          "id": "explain-carefully",
          "text": "Recommend B, give both first-try rates, and keep tracking results after the switch.",
          "quality": "strong",
          "replies": [
            {
              "from": "manager",
              "text": "I can use that: B had more patients repeat both steps on the first try, and we'll watch how it performs on every shift."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 20
            },
            {
              "meter": "slack",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You translated the test into a clear comparison and avoided promising the same result for every patient.",
              "example": null
            },
            {
              "skill": "chance",
              "kind": "good",
              "text": "You used a checked result, rather than the gap alone, to support the recommendation.",
              "example": null
            }
          ],
          "next": "adopt"
        },
        {
          "id": "wait-longer",
          "text": "Keep both scripts for now and ask for another review before changing shifts.",
          "quality": "fair",
          "replies": [
            {
              "from": "manager",
              "text": "We can do that, though keeping two scripts in use takes more coordination."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 5
            },
            {
              "meter": "slack",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Extra review is reasonable, but tell {{manager}} what the completed comparison already supports.",
              "example": "“B led in this comparison; I want one more review before we switch.”"
            }
          ],
          "next": "hold"
        },
        {
          "id": "promise",
          "text": "Recommend B and say it will make every patient understand on the first try.",
          "quality": "weak",
          "replies": [
            {
              "from": "manager",
              "text": "The results support a higher first-try rate, not a guarantee for each patient. I'll pause that wording."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "slack",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "A reliable group difference does not predict what will happen for every patient. State the observed rates instead.",
              "example": "“B had a higher first-try rate in this comparison.”"
            }
          ],
          "next": "corrected"
        }
      ]
    },
    {
      "id": "unverified",
      "messages": [
        {
          "from": "manager",
          "text": "I still need your recommendation. The switch remains on hold until we agree on what these counts mean."
        },
        {
          "from": "quality",
          "text": "Neither script has replaced the other. Patients who miss a step are still retaught before discharge."
        }
      ],
      "prompt": "What do you tell {{manager}} now?",
      "choices": [
        {
          "id": "state-limit",
          "text": "Say B is ahead so far, but ask for a sample plan and test before switching.",
          "quality": "strong",
          "replies": [
            {
              "from": "manager",
              "text": "That's a clear next step. We'll keep both approved scripts while the comparison continues."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 10
            },
            {
              "meter": "slack",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You said what the counts show and what they cannot yet establish.",
              "example": null
            },
            {
              "skill": "size",
              "kind": "good",
              "text": "You asked for a sample plan before making the broader change.",
              "example": null
            }
          ],
          "next": "hold"
        },
        {
          "id": "check-current",
          "text": "Ask {{ai}} to check the current gap, then defer a unit-wide switch.",
          "quality": "fair",
          "replies": [
            {
              "from": "ai",
              "text": "I checked the current counts. They do not give strong evidence that B is better: a gap this large is still fairly plausible by chance if the scripts work equally well. A sample plan is the next step."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 10
            },
            {
              "meter": "slack",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked the gap before making a claim and held off on a unit-wide change.",
              "example": null
            },
            {
              "skill": "size",
              "kind": "improve",
              "text": "The current check helps, but set a sample target before deciding when to compare again.",
              "example": null
            }
          ],
          "next": "hold"
        },
        {
          "id": "call-it",
          "text": "Recommend B for every shift because its lead has stayed at 10 points.",
          "quality": "weak",
          "replies": [
            {
              "from": "manager",
              "text": "I won't approve a unit-wide change from an unchecked lead. Let's keep the current supervision and review the comparison."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -15
            },
            {
              "meter": "slack",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Seeing the same gap again does not show that it is unlikely to be chance, especially with small groups.",
              "example": "“B is ahead so far, but we haven't established a reliable difference.”"
            }
          ],
          "next": "corrected"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "adopt",
      "outcome": "The unit adopts script B and continues tracking first-try teach-back. In the 400-per-group comparison, B reached 72.5% versus A's 62.5%; nurses still reteach any missed steps."
    },
    {
      "id": "hold",
      "outcome": "Both approved scripts stay in supervised use while the team completes its review. No unit-wide change is made yet, and nurses continue reteaching missed steps."
    },
    {
      "id": "corrected",
      "outcome": "The nurse manager pauses the recommendation rather than making a unit-wide change from an unsupported claim. Both approved scripts remain supervised while the team reviews the evidence."
    }
  ],
  "summary": [
    "A gap between two groups can appear by chance, especially when each group is small.",
    "Choose a sample size based on the difference that would matter before deciding when to stop collecting results.",
    "Explain what a test supports without promising the same outcome for every patient."
  ]
}

{
  "title": "O cupom mantém a margem da loja?",
  "setting": "Hoje, em uma loja de varejo",
  "mission": "Você precisa definir o preço de etiqueta antes de divulgar um cupom. Decida **se a venda com desconto atinge a meta de margem de 45%** e o que recomendar à gerência.",
  "deadline": "Divulgação da promoção hoje às 14h",
